import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { returnApplicationHandler } from "../handlers/returnApplicationHandler";
import type { ApiError } from "../runtime/client";
import type { ApplicationReturnCommentRequest } from "../types/ApplicationReturnCommentRequest";
import type { TeamPartition } from "../types/TeamPartition";

type Data = Awaited<ReturnType<typeof returnApplicationHandler>>;
type Vars = { teamPk: TeamPartition; applicationId: string; body: ApplicationReturnCommentRequest };

export function useReturnApplication(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => returnApplicationHandler(vars.teamPk, vars.applicationId, vars.body),
    ...options,
  });
}
